create role anon;create role authenticated;create role service_role bypassrls;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.user_id',true),'')::uuid$$;
create table organizations(id uuid primary key);
create table organization_members(organization_id uuid,user_id uuid,role text);
create table agents(id uuid primary key,enabled boolean default true);
create table projects(id uuid primary key,organization_id uuid,name text,project_type text default 'business_project',status text default 'active',lifecycle_state text default 'EXECUTION',stage text,workflow_state text,completion_policy_id uuid,completion_overrides jsonb default '{}',completion_metadata jsonb default '{}',blocker_type text,blocker_summary text,resolution_required text,budget_cap_usd numeric,
work_progress smallint default 0,deliverable_progress smallint default 0,implementation_progress smallint default 0,verification_progress smallint default 0,outcome_progress smallint default 0,acceptance_progress smallint default 0,closeout_progress smallint default 0,overall_project_progress smallint default 0,progress_percent smallint default 0,completion_eligible boolean default false,completion_evaluated_at timestamptz,completion_evaluator_version text,next_required_action text,completion_blocking_reasons jsonb,completion_satisfied_criteria jsonb,updated_at timestamptz default now());
create table project_agents(project_id uuid,organization_id uuid,agent_id uuid,assignment_role text,status text);
create table project_roadmaps(id uuid primary key default gen_random_uuid(),project_id uuid,status text,is_baseline boolean);
create table project_roadmap_phases(id uuid primary key default gen_random_uuid(),project_id uuid,organization_id uuid,status text,title text,description text,success_criteria jsonb default '[]',deliverables jsonb default '[]',outcome_progress_percent numeric,updated_at timestamptz default now());
create table project_executions(id uuid primary key default gen_random_uuid(),organization_id uuid,project_id uuid,execution_no integer,status text,execution_context jsonb,plan_snapshot jsonb,budget_snapshot jsonb,started_at timestamptz,last_heartbeat_at timestamptz,last_progress_at timestamptz,unique(project_id,execution_no));
create table project_task_runs(id uuid primary key default gen_random_uuid(),organization_id uuid,project_id uuid,execution_id uuid,roadmap_phase_id uuid,task_key text,title text,assigned_agent_id uuid,status text,priority integer,dependencies jsonb,idempotency_key text unique,input jsonb,work_weight numeric,safe_result jsonb);
create table project_completion_policies(id uuid primary key default gen_random_uuid(),organization_id uuid,code text,required_dimensions jsonb,weights jsonb,allow_residual_risk_acceptance boolean default false,observation_required boolean default false,unresolved_blockers_prevent_closure boolean default true,created_at timestamptz default now());
create table project_completion_criteria(id uuid primary key default gen_random_uuid(),project_id uuid,organization_id uuid,criterion_key text,dimension text,description text,required boolean default true,state text default 'pending',source_entity_type text,source_entity_id uuid,validator_type text,metadata jsonb default '{}',waiver_reason text,waiver_approver_user_id uuid,waived_at timestamptz,failure_reason text,created_at timestamptz default now(),unique(project_id,criterion_key));
create table project_completion_evidence(id uuid primary key default gen_random_uuid(),project_id uuid,organization_id uuid,criterion_id uuid,authoritative_source boolean default false,verification_result text,lifecycle_dimension text,collected_at timestamptz default now(),structured_data jsonb default '{}');
create table project_observation_windows(id uuid primary key default gen_random_uuid(),project_id uuid,organization_id uuid,required_duration_days integer,status text,sufficient_data boolean default false,observation_start timestamptz,observation_end timestamptz);
create table project_metric_measurements(id uuid primary key default gen_random_uuid(),project_id uuid,organization_id uuid,metric_name text,measurement_kind text default 'outcome',value numeric,source text,evidence_id uuid,measurement_start timestamptz,measurement_end timestamptz);
create table project_closeout_reports(project_id uuid,status text);
create table project_activity_events(id uuid primary key default gen_random_uuid(),organization_id uuid,project_id uuid,event_type text,headline text,detail text,importance text,metadata jsonb);
create table audit_events(organization_id uuid,actor_type text,actor_user_id uuid,event_type text,object_type text,object_id uuid,risk_level text,payload jsonb);
create table approval_requests(id uuid primary key default gen_random_uuid(),organization_id uuid,project_id uuid,status text,resolved_at timestamptz,subject_id uuid,subject_type text,title text,requested_by_agent_id uuid);
create table project_proposals(id uuid primary key,project_id uuid,organization_id uuid,source_task_run_id uuid);
create table project_completion_evaluations(id uuid primary key default gen_random_uuid(),organization_id uuid,project_id uuid,previous_state text,new_state text,eligible_for_completion boolean,work_progress smallint,deliverable_progress smallint,implementation_progress smallint,verification_progress smallint,outcome_progress smallint,acceptance_progress smallint,closeout_progress smallint,overall_project_progress smallint,blocking_reasons jsonb,satisfied_criteria jsonb,next_required_action text,evaluator_version text,triggered_event text,source_type text,source_id uuid,evidence_references jsonb);
grant usage on schema public,auth to authenticated,service_role;
grant select on organization_members to authenticated;
grant execute on function auth.uid() to authenticated;
grant all on all tables in schema public to service_role;
